}

const data = parseJson($json.text) || {};
const tasks = Array.isArray(data.rated_tasks) ? data.rated_tasks
            : (Array.isArray(data.tasks) ? data.tasks : []);

const W = { urgency: 0.40, revenue: 0.35, customer: 0.25 };
const clamp = (n) => Math.max(1, Math.min(5, Number(n) || 1));

const ranked = tasks.map(t => {
  const u = clamp(t.urgency), r = clamp(t.revenue_impact), c = clamp(t.customer_impact);
  const composite = +(W.urgency * u + W.revenue * r + W.customer * c).toFixed(2);
  const score_100 = Math.round(composite * 20);
  let bucket = 'Backlog';
  if (composite >= 4) bucket = 'Critical';
  else if (composite >= 2.8) bucket = 'Important';
  return { id: t.id, description: t.description, urgency: u, revenue_impact: r,
           customer_impact: c, rationale: t.rationale || '', composite, score_100, bucket };
}).sort((a, b) => b.composite - a.composite);

return [{ json: { ranked_tasks: ranked } }];

