const data = parseJson($json.text) || {};
const list = Array.isArray(data.bottlenecks) ? data.bottlenecks : [];
const THRESHOLD = 3;

const bottlenecks = list.map(b => {
  const freq = Number(b.frequency) || 0;
  return { theme: b.theme, frequency: freq, evidence: b.evidence || '',
           impact: b.impact || '', systemic: freq >= THRESHOLD };
}).sort((a, b) => b.frequency - a.frequency);

return [{ json: { bottlenecks } }];

const items = $input.all();
let ranked_tasks = [], bottlenecks = [];
for (const it of items) {
  if (Array.isArray(it.json.ranked_tasks)) ranked_tasks = it.json.ranked_tasks;
  if (Array.isArray(it.json.bottlenecks)) bottlenecks = it.json.bottlenecks;
}
return [{ json: { ranked_tasks, bottlenecks } }];

function parseJson(raw) {
  if (raw == null) return null;
  let s = String(raw).trim();
  s = s.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a !== -1 && b !== -1) s = s.slice(a, b + 1);
