}

const plan = parseJson($json.text) || {};
const top = Array.isArray(plan.top_3_priorities) ? plan.top_3_priorities : [];
const quick = Array.isArray(plan.quick_wins) ? plan.quick_wins : [];
const deleg = Array.isArray(plan.delegate) ? plan.delegate : [];
const risk = plan.biggest_risk || '';
const plan_valid = top.length > 0 && String(risk).length > 0;

const line = (x, i) => `${i + 1}. ` + (typeof x === 'string'
  ? x
  : (x.title ? `${x.title}${x.why ? ' - ' + x.why : ''}` : JSON.stringify(x)));

const summary = [
  'TOP 3 PRIORITIES:', top.map(line).join('\n') || '(none)', '',
  'BIGGEST RISK:', risk || '(none)', '',
  'QUICK WINS:', quick.map(line).join('\n') || '(none)', '',
  'DELEGATE:', deleg.map(line).join('\n') || '(none)', '',
  'SUMMARY:', plan.summary || '(none)'
].join('\n');

return [{ json: { plan_valid, plan, plan_summary: summary } }];
